//////////////////////////////////////////////////////////////////
//
// Concentric Xor, mla, 2023
//
// SDFs are nice for logical combinations of primitives,
// including xor (aka symmetric difference):
//
// xor(A,B) = intersect(union(A,B),complement(intersect(A,B)))
//
// 'd': show distance field
// 'r': randomly perturb radii
// 'x': show boundaries of regions
//
// Based on on https://www.shadertoy.com/view/ctSGzV by AxisPod
//
//////////////////////////////////////////////////////////////////

// SDF xor
float xor(float d0, float d1) {
  // Union minus the intersection
  return max(min(d0,d1),-max(d0,d1));
}

float repCircle(vec2 p, float t, vec2 centre) {
  p -= centre;
  float r = length(p);
  float i = round(r/t);
  if (i == 0.0) i = 1.0; // No boundary at 0
  float s = t*i; // s is nearest boundary
  if (key(CHAR_R)) s += 0.5*t*(rand(int(i))-0.5); // Random perturbation
  float sgn = mod(i,2.0) == 0.0 ? -1.0 : 1.0;
  assert(sgn < 0.0);
  return sgn*(r-s);
}

float repSquare(vec2 p, float t, vec2 centre) {
  p -= centre;
  p = abs(p);
  float r = min(p.x,p.y);
  float i = round(r/t);
  if (i == 0.0) i = 1.0; // No boundary at 0
  float s = t*i; // s is nearest boundary - adjust here if desired
  if (key(CHAR_R)) s += 0.5*t*(rand(int(i)*255)-0.5); // Random perturbation
  float sgn = mod(i,2.0) == 0.0 ? -1.0 : 1.0;
  float dx = s-p.x;
  float dy = s-p.y;
  // We could just return max(dx,dy) but it doesn't cost
  // much to get an exact distance.
  float d = dx > 0.0 && dy > 0.0 ? distance(p,vec2(s)) : max(dx,dy);
  return sgn*d;
}

vec3 drawScene(vec2 p) {
  float px = fwidth(p.x);
  float t = 0.25*iTime;
  float d1 = repCircle(p, 0.5, vec2(sin(t)*1.0, cos(0.414*t)*1.5));
  float d2 = repSquare(p, 0.5, vec2(-sin(0.618*t)*1.5, cos(t))*1.0);
  float d = xor(d1,d2);
  vec3 col = vec3(smoothstep(-0.5*px,0.5*px,d));
  if (key(CHAR_D)) col *= 0.75-0.25*cos(0.5*PI*d/px);
  if (key(CHAR_X)) col = mix(vec3(1,0,0),col,smoothstep(0.0,px,abs(d)-0.005));
  return col;
}

void mainImage(out vec4 fragColor, vec2 fragCoord ) {
  vec2 p = (fragCoord-0.5*iResolution.xy)/iResolution.y;
  p *= 4.0;
  vec3 col = drawScene(p);
  col = pow(col,vec3(0.4545));
  if (key(CHAR_A) && alert) col.b = 1.0-col.b;
  fragColor = vec4(col,1);
}

common_code:
bool alert = false;
void assert(bool b) { if (!b) alert = true; }

const float PI = 3.14159;

const int CHAR_A = 65;
const int CHAR_D = 68;
const int CHAR_R = 82;
const int CHAR_X = 88;
const int CHAR_Y = 89;
const int CHAR_Z = 90;

#define key(code) (texelFetch(iChannel3, ivec2((code),2),0).x != 0.0)

uint ihash(uint x) {
  x += 0x12345678u;
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}

float rand(int n) {
  return float(ihash(uint(n)))/exp2(32.0);
}
